"""Genera el documento tecnico de diez paginas. Requiere reportlab."""
from pathlib import Path
from xml.sax.saxutils import escape
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, Table, TableStyle, Image, Preformatted
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER
raiz=Path(__file__).resolve().parents[1]
salida=raiz/'doc/Documento-tecnico.pdf'
estilos=getSampleStyleSheet()
estilos.add(ParagraphStyle(name='Texto', fontName='Helvetica',fontSize=10,leading=14,spaceAfter=9))
estilos.add(ParagraphStyle(name='CodigoLocal',fontName='Courier',fontSize=8,leading=11))
estilos.add(ParagraphStyle(name='Portada',fontName='Helvetica-Bold',fontSize=30,leading=36,textColor=colors.HexColor('#38204b'),spaceAfter=24))
estilos['Heading1'].textColor=colors.HexColor('#38204b')
estilos['Heading2'].fontSize=13
flujo=[]
def p(t): flujo.append(Paragraph(escape(t),estilos['Texto']))
def h(t): flujo.append(Paragraph(escape(t),estilos['Heading2']))
def pagina(t):
 if flujo:flujo.append(PageBreak())
 flujo.append(Paragraph(escape(t),estilos['Heading1']))
def tabla(filas,anchos):
 celdas=[[Paragraph(escape(str(c)),estilos['Texto']) for c in fila] for fila in filas]
 t=Table(celdas,colWidths=anchos,repeatRows=1,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e5deeb')),('GRID',(0,0),(-1,-1),0.4,colors.HexColor('#aaa0b1')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),3)]))
 flujo.append(t);flujo.append(Spacer(1,10))
def foto(nombre,w,h):flujo.append(Image(str(raiz/'doc'/nombre),width=w,height=h));flujo.append(Spacer(1,10))
pagina('Clave Espectral')
flujo.append(Spacer(1,25));flujo.append(Paragraph('Documento tecnico',estilos['Portada']))
p('Proyecto de Mastermind en ensamblador x86 de 16 bits. Michelle Wittingham y Sofia Bejarano. Revision tecnica: 1 de noviembre de 2026.')
h('Proposito')
p('El jugador deduce una clave de personajes de Halloween a partir de intentos limitados. Los aciertos exactos se muestran como toros verdes y las fichas correctas en otra posicion como vacas naranjas. La tematica conserva las reglas de Mastermind con ocho personajes distintos.')
h('Plataforma')
p('Modelo SMALL, pila de 256 bytes, BIOS y DOS. El programa usa VGA modo 13h, 320 x 200 pixeles y un byte por pixel. La logica y el dibujo se ejecutan en ensamblador; las herramientas auxiliares solo construyen, exportan y documentan.')
h('Estado de esta version')
p('Se ensamblo con TASM 3.2 y se enlazo con TLINK 3.01 en DOSBox. Los registros de bin documentan la compilacion y las pruebas automatizadas. Esta documentacion debe ser revisada por ambas integrantes para su defensa y adaptada con su experiencia real.')
p('La bitacora semanal, la confirmacion de autoria original de los dibujos y la declaracion personal de aportes siguen siendo responsabilidad de las integrantes. No se inventaron horas ni actividades individuales.')
pagina('1. Reglas y requisitos funcionales')
tabla([['Nivel','Posiciones','Fichas','Repetidos','Intentos'],['Facil',4,6,'No',12],['Normal',4,6,'Si',10],['Dificil',5,8,'Si',10]],[90,80,70,100,100])
p('El menu ofrece Jugar, Dificultad, Instrucciones, Creditos y Salir. La dificultad se conserva durante la ejecucion. Una partida nueva reinicia el intento, el historial y los contadores y genera otra clave.')
h('Ciclo de una jugada')
p('Izquierda y derecha cambian de casilla. Arriba, abajo o las teclas 1..C cambian su ficha. Backspace la borra. Enter comprueba que todas las posiciones esten llenas y evalua la fila. El intento incompleto no consume turno y muestra un aviso.')
p('Cada fila evaluada permanece visible con sus dos pistas y queda tambien guardada en DATA. Al acertar todas las posiciones se muestra la victoria; al agotar intentos, la derrota. En ambos casos se revela la clave y Enter permite iniciar otra partida sin salir de DOS.')
h('Modo de revision')
p('F2 desde el menu abre un editor de clave para las pruebas del docente. Se escriben N digitos dentro de 1..C y se confirma con Enter. Este modo identifica la partida como PRUEBA MANUAL y permite repetidos para ejecutar los ejemplos oficiales. Las partidas aleatorias siguen las reglas del nivel.')
h('Correspondencia')
p('RF-01 a RF-14 estan cubiertos por portada animada, menu, instrucciones, generacion, controles, validacion, evaluacion, historial, indicadores, resultado, reinicio y salida ordenada. La auditoria detallada y los pendientes de entrega estan en doc/REVISION.md.')
pagina('2. Algoritmo de toros y vacas')
h('Primera pasada: toros')
p('EvaluarIntento limpia dos arreglos de cinco marcas. Recorre las N posiciones: cuando intento[i] coincide con secreto[i], incrementa AciertosExactos y marca ambos indices como usados. Asi una coincidencia exacta queda reservada antes de buscar coincidencias fuera de posicion.')
h('Segunda pasada: vacas')
p('Por cada ficha del intento que no se conto como toro, se busca una ficha igual en el secreto que todavia no este usada. Al encontrarla se incrementa AciertosOtraPosicion, se reserva esa ficha del secreto y se termina esa busqueda. Si no se encuentra ninguna disponible, no suma pista.')
h('Por que cuenta bien las repeticiones')
p('Una posicion del secreto puede pasar de libre a usada una sola vez. Una ficha del intento genera como maximo una pista y las exactas se reservan primero. Por eso un tercer personaje repetido no obtiene pista si el secreto solo tiene dos copias. Siempre se cumple toros + vacas <= N.')
tabla([['Secreto','Intento','Toros','Vacas'],['1234','1324',2,2],['1123','1211',1,2],['1234','5656',0,0],['3333','3311',2,0]],[130,130,90,90])
p('Equivalencias del enunciado: R=1, V=2, A=3, M=4, N=5 y B=6. Los cuatro ejemplos se ejecutan directamente contra EvaluarIntento en el modo /T. El algoritmo tiene coste O(N cuadrado), con N como maximo 5; resulta pequeno y facil de seguir en 8086.')
pagina('3. Datos, memoria y coordenadas')
tabla([['Dato','Tamano','Uso'],['CodigoSecreto / IntentoActual','5 bytes cada uno','Una ficha por posicion; 0 significa vacia.'],['Historial','60 bytes','12 filas por cinco posiciones. Offset = turno * 5 + posicion.'],['HistorialToros / HistorialVacas','12 bytes cada uno','Pistas asociadas a cada fila.'],['UsadoSecreto / UsadoIntento','5 bytes cada uno','Evitar contar dos veces las coincidencias.'],['TurnoActual / PosicionActual','1 byte cada uno','Indices con base cero.'],['FilaJuego','1 palabra','Coordenada vertical de la fila en construccion.'],['Fichas / FichasAnimadas','8 palabras cada una','Offsets de los cuadros de los personajes.']],[160,110,170])
h('Segmentos')
p('DS apunta a DATA. ES apunta a A000h durante el dibujo. SS identifica la pila; las rutinas equilibran PUSH y POP y conservan los registros que no devuelven como resultado. Las cadenas de ESCRIBIR_TEXTO quedan incrustadas en CODE y la macro salva y restaura DS para leerlas.')
h('Memoria de video')
p('El pixel (x,y) ocupa el desplazamiento y * 320 + x dentro de A000h. La pantalla contiene 64000 bytes. El fondo y las formas se escriben con REP STOSB o directamente mediante ES:[DI]; no se usan interrupciones BIOS por pixel.')
p('Encabezado: (0,0), 320x20. Tablero: (4,22), 196x168. Lateral: (204,22), 112x168. Estado: (0,190), 320x10. Se usan pasos verticales de 13 pixeles para que los 12 intentos de Facil entren en la misma zona; Normal y Dificil usan 10 filas.')
pagina('4. Paleta VGA personalizada')
p('CargarPaleta escribe el indice inicial en 03C8h y luego 27 tripletas RGB en 03C9h. Cada componente del DAC va de 0 a 63. Los primeros colores pertenecen a textos y personajes; 21..26 definen el tablero. El indice 0 no se dibuja al renderizar sprites y 8 es negro visible.')
filas=[['Indice','R','G','B','Uso']]
colores=[]
for linea in (raiz/'src/paleta.inc').read_text().splitlines():
 if linea.startswith('DB '):colores.append([int(x.strip()) for x in linea[3:].split(';')[0].split(',')])
for i,c in enumerate(colores):
 uso={0:'Transparencia',3:'Texto blanco',7:'Toros / seleccion',8:'Negro',12:'Vacas',21:'Fondo',22:'Panel',23:'Casilla clara',24:'Borde',25:'Acento',26:'Detalle'}.get(i,'Sprite / interfaz')
 filas.append([i,*c,uso])
# Tabla compacta para conservar una sola pagina.
t=Table([[str(c) for c in f] for f in filas],colWidths=[60,45,45,45,245],hAlign='LEFT');t.setStyle(TableStyle([('FONT',(0,0),(-1,-1),'Helvetica',9),('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e5deeb')),('GRID',(0,0),(-1,-1),0.3,colors.grey),('TOPPADDING',(0,0),(-1,-1),3),('BOTTOMPADDING',(0,0),(-1,-1),3)]));flujo.append(t)
pagina('5. Modulos y paso de parametros')
tabla([['Archivo','Responsabilidad'],['prueba.asm','Inicializacion, estado global y navegacion.'],['juego.inc','Reglas, clave, evaluacion, historial y teclado del juego.'],['interfaz.inc','Personajes, cursores, indicadores, resultado y clave manual.'],['video.inc','Paleta, limpieza, rectangulos y DibujarSprite.'],['animar.inc','Reloj y cuadros de portada, seleccion y resultado.'],['dific.inc / menu.inc','Navegacion y selectores.'],['pruebas.inc','Pruebas /T y capturas de verificacion.'],['figuras.inc / cuadros.inc','Datos originales y cuadros alternativos.']],[170,270])
h('Flujo de llamadas')
p('MAIN -> IniciarPartida -> GenerarCodigo; MAIN -> PantallaJuego -> ControlarJuego -> EditarIntento -> ConfirmarIntento. La confirmacion llama EvaluarIntento, GuardarHistorial y DibujarPistas. Un resultado terminal abre PantallaFin. Las esperas consultan el teclado sin bloquear las animaciones ni el apagado del altavoz.')
h('Contrato de dibujo')
p('PINTAR_RECT apila X, Y, ancho, alto y color como palabras; DibujarRectangulo devuelve con RET 10. PINTAR_IMAGEN apila siete palabras: X, Y, ancho destino, alto destino, ancho origen, alto origen y offset de datos. DibujarSprite retira 14 bytes y conserva los registros de trabajo.')
p('DibujarPersonaje recibe AL como identificador, BX como X, DX como Y y CX como tamano. Una tabla de offsets evita ocho rutinas de dibujo repetidas. Los encabezados de PROC documentan las entradas, salidas y preservacion de registros.')
pagina('6. Sprites y cuadros de animacion')
p('Cada ficha contiene 256 bytes, recorridos de izquierda a derecha y de arriba abajo. Los ceros son transparentes. Hay ocho fichas para el nivel Dificil y una mascota para la portada. La hoja muestra el cuadro base y el alternativo; las tablas estan en figuras.inc y cuadros.inc.')
foto('hoja-sprites.png',440,367)
p('Los cuadros alternativos desplazan parte de la postura y modifican los ojos para producir un movimiento visible. No se cargan imagenes externas durante el juego. herramientas/exportar_sprites.py reconstruye esta hoja y doc/PALETA.md a partir de los bytes de ensamblador.')
p('Las integrantes deben confirmar la autoria original de los dibujos base y conservar sus bocetos o archivos de creacion. No se afirma procedencia propia sin su comprobacion.')
pagina('7. Teclado, tiempo y dibujo sin parpadeo')
h('ASCII y codigos de exploracion')
p('INT 16h AH=01h consulta si existe una tecla y permite seguir actualizando la pantalla. AH=00h consume la tecla disponible. AL contiene ASCII para Enter, Esc, Backspace y numeros; AH distingue izquierda 4Bh, derecha 4Dh, arriba 48h y abajo 50h. F2 usa 3Ch en el menu.')
h('Tres animaciones')
p('AvanzarAnimacion lee los ticks mediante INT 1Ah AH=00h. Si han pasado al menos cuatro ticks alterna CuadroAnimacion y devuelve CF=1. La portada usa un fantasma de dos cuadros; el lateral anima el personaje seleccionado; el resultado usa una calabaza que salta al ganar y un fantasma que se sacude al perder.')
p('El tiempo procede del BIOS, no de un bucle contado por velocidad de CPU. Una resta modular de la palabra baja de ticks tolera el desbordamiento del contador. El bucle nunca espera que termine una animacion para leer una tecla.')
h('Actualizacion parcial')
p('Al mover la casilla se borra solo el cursor anterior. Al editar se limpia y dibuja solo esa ficha. La animacion lateral actualiza su recuadro de 16x16; los cambios de menu actualizan el selector. Las pantallas completas se dibujan al entrar, no en cada ciclo de espera.')
h('Margenes y sonidos')
p('El menu limpia tambien los margenes que antes dejaban visible el mensaje inferior del tablero. SonidoSeleccion activa el altavoz y ActualizarSonido lo apaga tras dos ticks. ApagarSonido se llama antes de volver al menu o cerrar DOS, sin bucles de demora que bloqueen el teclado.')
pagina('8. Verificacion y resultados')
p('La construccion de esta version se ejecuto en DOSBox con TASM 3.2 y TLINK 3.01. El resultado fue cero errores y cero advertencias. bin/BUILD.LOG, bin/LINK.LOG y bin/TESTS.LOG conservan la evidencia reproducible.')
tabla([['Prueba','Comprobacion'],['Cuatro casos oficiales','Evalua las mismas tablas con la rutina real del juego.'],['Tres dificultades','Valores dentro de rango y sin duplicados en Facil.'],['Intento incompleto','No modifica TurnoActual.'],['Backspace','Vacia la posicion activa y conserva la otra.'],['Victoria','Introduce la clave con EditarIntento, gana y guarda cuatro toros.'],['Derrota','Diez intentos fallidos; resultado terminal y ultima fila del historial.']],[140,300])
foto('dificil.png',440,275)
p('Las capturas son volcados reales de A000h durante /T, convertidos con la paleta del programa. La inspeccion visual confirma las zonas, los ocho personajes de Dificil y los indicadores. Es recomendable que ambas autoras jueguen tambien de forma interactiva antes de la defensa.')
pagina('9. Construccion, dificultades y entrega')
h('Construccion reproducible')
p('El comando de README ejecuta herramientas/compilar.ps1 -Pruebas. El script usa una carpeta temporal, copia las fuentes y las herramientas locales, ejecuta TASM y TLINK y luego el modo /T. Solo publica bin/CLAVE.EXE cuando la compilacion produjo un ejecutable; exige OK en las pruebas. dosbox.conf permite iniciar la entrega desde la raiz del repositorio.')
h('Problemas corregidos')
p('Se corrigieron INCLUDE que no coincidian con nombres de archivos, nombres incompatibles con DOS 8.3 y saltos condicionales de alcance corto. La directiva JUMPS de TASM y los saltos SHORT donde corresponden permiten ensamblado limpio sin instrucciones de 386. Se corrigio tambien un indice 164 del buho que no pertenecia a la paleta cargada.')
p('La evaluacion anterior confirmaba con Espacio y no avisaba ante filas incompletas. Ahora Enter evalua, Backspace borra y se muestran avisos. El historial se almacena en tablas ademas de permanecer dibujado, y el fin revela la clave y permite reinicio.')
h('Uso de IA y pendientes personales')
p('Se uso Codex para explicar ensamblador y para proponer, generar y depurar partes del codigo, las pruebas y esta documentacion. Las integrantes deben revisar cada rutina, adaptar la redaccion y declarar los aportes de la herramienta en la entrega. No se debe presentar esta descripcion como una bitacora individual ni como prueba de autoria de los dibujos.')
p('Pendiente de las integrantes: completar una pagina de bitacora por semana con actividades reales; confirmar originalidad de sprites; preparar la defensa y, opcionalmente, grabar un video de 3 a 5 minutos con una victoria y una derrota. No se implementaron puntajes persistentes, modo inverso, dos jugadores, cronometro ni fade, que son opcionales.')
def pie(canvas,doc):
 canvas.setStrokeColor(colors.HexColor('#b7a7c4'));canvas.line(48,45,547,45)
 canvas.setFont('Helvetica',8);canvas.setFillColor(colors.HexColor('#584963'))
 canvas.drawString(48,32,'Clave Espectral | Documento tecnico para revision de las autoras')
 canvas.drawRightString(547,32,str(doc.page))
SimpleDocTemplate(str(salida),pagesize=(595.28,841.89),rightMargin=64,leftMargin=64,topMargin=48,bottomMargin=58,title='Clave Espectral - Documento tecnico',author='Michelle Wittingham y Sofia Bejarano; asistencia de Codex').build(flujo,onFirstPage=pie,onLaterPages=pie)
print(salida)
